@keyframes menuIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
@keyframes livePulse{0%,100%{box-shadow:0 0 0 0 rgba(232,182,76,.35)}50%{box-shadow:0 0 0 6px rgba(232,182,76,0)}}
